/* Global Office */

Office.onReady();

function insertCompanySignature(event: Office.AddinCommands.Event) {
  // 1. Haal de direct beschikbare profielgegevens op uit Outlook
  const userName = Office.context.mailbox.userProfile.displayName;
  const userEmail = Office.context.mailbox.userProfile.emailAddress;
  
  // 2. Haal het aanpasbare veld op dat de gebruiker in de Task Pane heeft ingevuld
  const customField = localStorage.getItem("DeOever_CustomText") || "";

  // 3. TODO: Hier komt later de Microsoft Graph API call om Job Title & Office te laden.
  // Voor nu gebruiken we tijdelijke placeholders om te testen.
  const jobTitle = "Medewerker De Oever"; 
  const officeLocation = "Hoofdkantoor";

  // 4. Bouw de onwijzigbare HTML-structuur gecombineerd met het aanpasbare veld
  const signatureHtml = `
    <div style="font-family: 'Segoe UI', Arial, sans-serif; font-size: 14px; color: #333; margin-top: 20px;">
      <p style="margin-bottom: 15px;">Met vriendelijke groet,</p>
      <strong style="font-size: 16px; color: #0078d4;">${userName}</strong><br>
      <span style="color: #555; font-weight: 500;">${jobTitle}</span><br>
      <span style="color: #777; font-size: 13px;">Kantoor: ${officeLocation} | ${userEmail}</span>
      
      ${customField ? `<div style="margin-top: 8px; color: #d83b01; font-style: italic; font-size: 13px;">\${customField}</div>` : ""}
      
      <div style="margin-top: 15px; border-top: 1px solid #e0e0e0; padding-top: 10px;">
        <img src="https://deoever.be" alt="De Oever" width="120" style="display: block; margin-bottom: 5px;">
        <small style="color: #a19f9d; font-size: 11px; display: block; line-height: 1.3;">
          Dit bericht en eventuele bijlagen zijn vertrouwelijk.
        </small>
      </div>
    </div>
  `;

  // 5. Injecteer de handtekening geruisloos onderaan de e-mail
  Office.context.mailbox.item.setSignatureAsync(
    signatureHtml,
    { coercionType: Office.CoercionType.Html },
    (result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        console.error("Handtekening mislukt: " + result.error.message);
      }
      
      // 6. VERPLICHT: Meld aan Outlook dat de achtergrondtaak succesvol is afgerond
      event.completed();
    }
  );
}

// Koppel de functie aan de naam die in het manifest staat vermeld
Office.actions.associate("insertCompanySignature", insertCompanySignature);
